define({"topics":[{"title":"B0 Drift tool","href":"t_B0DriftTool_Parent.html","attributes":{"data-id":"id_2001624"},"menu":{"hasChildren":true},"tocID":"id_2001624-d46e2478","next":"id_2001624-d46e2478"},{"title":"Doing DQA calibration with the DQA III phantom","shortdesc":"<p class=\"shortdesc\">The DQA tool determines correct gradient polarity and correct gradient wiring by scanning a series of axial and coronal images of the DQA III phantom for systems below sentence MR 31.0 or sites that do not have a 17cm Sphere with Spout (SWS) phantom.<\/p>","href":"t_DoingDQACalibration.html","attributes":{"data-id":"id_2001635"},"menu":{"hasChildren":false},"tocID":"id_2001635-d46e2980","topics":[]},{"title":"Doing DQA calibration <span class=\"ph\">with the Sphere With Spout (SWS) phantom<\/span>","shortdesc":"<p class=\"shortdesc\">Details the steps needed to run the Gradient Calibration Tool (GCT) for systems running MR31.0 and higher<span class=\"ph\"> and that possess the 17cm Sphere with Spout (SWS) phantom<\/span>. GCT does the same checks and produces the same output as DQA.<\/p>","href":"t_DoingDQACalibrationsforMR31andHigher.html","attributes":{"data-id":"id_2068424"},"menu":{"hasChildren":false},"tocID":"id_2068424-d46e3082","topics":[]},{"title":"Running LVShim - Gradshim","shortdesc":"<p class=\"shortdesc\"\/>","href":"t_RunningLVShimGradshim_Parent_DoNotUse.html","attributes":{"data-id":"id_2024932"},"menu":{"hasChildren":true},"tocID":"id_2024932-d46e3190","next":"id_2024932-d46e3190"},{"title":"Doing system gain calibration ","href":"t_CalibratingSystemGain.html","attributes":{"data-id":"id_2001851"},"menu":{"hasChildren":false},"tocID":"id_2001851-d46e3704","topics":[]},{"title":"Doing the Multi-Coil Quality Assurance (MCQA) check","shortdesc":"<p class=\"shortdesc\">The Multi-Coil Quality Assurance (MCQA) tool simplifies data acquisition and analysis of the signal-to-noise ratio (SNR) for surface coils.<\/p>","href":"t_DoingTheMulti-CoilQualityAssuranceMCQACheck.html","attributes":{"data-id":"id_2001637"},"menu":{"hasChildren":false},"tocID":"id_2001637-d46e3804","topics":[]},{"title":"Calibrating PROBE Tuning and SNR Check","shortdesc":"<p class=\"shortdesc\">This tool runs both Echo Peak Location calibration (automated probe tuning script) and the probe signal-to-noise ratio (SNR) performance test.<\/p>","href":"t_CalibratingProbeSVAndTestingSNR.html","attributes":{"data-id":"id_2001552"},"menu":{"hasChildren":false},"tocID":"id_2001552-d46e3908","topics":[]}]});